using CouponBook.Api.Dtos;using CouponBook.Business.Sales;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace CouponBook.Api.Controllers;
[ApiController][Route("api")][Authorize(Roles="Customer")]public class PurchaseController:ControllerBase{private readonly IPurchaseService _p;public PurchaseController(IPurchaseService p)=>_p=p;private int U=>int.Parse(User.FindFirst("sub")!.Value);[HttpPost("books/{id:int}/purchase")]public async Task<IActionResult>Purchase(int id,PurchaseRequest q){var r=await _p.StartPurchaseAsync(U,id,new(q.PromoCode,q.IsGift,q.RecipientMobile,q.GiftMessage,q.PaymentMethod));return r.Succeeded?Created($"/api/orders/{r.Value!.OrderId}",r.Value):BadRequest(new{code=r.ErrorCode,errors=r.Errors});}[HttpGet("orders/{id:int}")]public async Task<IActionResult>Order(int id){var x=await _p.GetOrderAsync(U,id);return x==null?NotFound():Ok(x);}[HttpGet("my/books")]public async Task<IActionResult>Books()=>Ok(await _p.GetMyBooksAsync(U));}
